% PONIIMPORT - import a poni calibration file generated by pyFAI/DIOPTAS
%
% This method imports a poni file and updates the geometry accordingly. It
% assumes the wavelength and pixel sizes are consistent but warns the user
% if it detects > 0.01% deviations in these values and outputs a cell
% array of related warnings. This method assumes the image has not been
% flipped or rotated in Dioptas and forces the MATLAB default orientation
% on the SMASH image (ie YDir = 'reverse').
%
% Usage:
%   >> [obj, problems] = poniImport(obj, poniFile)
%   >> [obj, problems] = poniImport(obj, poniFile, conv)
%       -> conv is the ratio of the obj unit to meters (default is 1e-3)
%
% created November, 2026 by Nathan Brown (Sandia National Laboratories)
%
function [obj, problems] = poniImport(obj, poniFile, varargin)

% input parsing

assert(isa(obj.detector.image,'SMASH.ImageAnalysis.Image'), ...
    'No detector image!')
conv = 1e-3; % DENNIS assumes mm
if nargin > 2
    conv = varargin{1};
end

% read poni

params = readPoni(poniFile);

% apply poni to detector

obj.detector.image.GraphicOptions.YDir = 'reverse';
obj = changeObject(obj, 'crystal', 'location', [0 0 0]);
obj = changeObject(obj, 'source', 'location', [0 -10 0]);
obj = changeObject(obj, 'detector', 'location', [0 0 0]);
obj = resetOrientation(obj, 'detector');

sz = obj.detector.size / 2;
obj = changeObject(obj, 'detector', 'location', ...
    [sz(2)-params.Poni2/conv, params.Distance/conv, sz(1)-params.Poni1/conv]);
obj = applyRotations(obj,params);

% check consistencies

problems = checkConsistencies(obj,params,conv,1e-4);

end

%% poni reading
function params = readPoni(poniFile)
str = string(fileread(poniFile));

params.Distance = str2double(extractBetween(str,'Distance:',newline));
params.Poni1 = str2double(extractBetween(str,'Poni1:',newline)); % m
params.Poni2 = str2double(extractBetween(str,'Poni2:',newline));
params.Rot1 = str2double(extractBetween(str,'Rot1:',newline)); % rad
params.Rot2 = str2double(extractBetween(str,'Rot2:',newline));
params.Rot3 = str2double(extractBetween(str,'Rot3:',newline));

params.Wavelength = str2double(extractBetween(str,'Wavelength:',newline));
params.pixel1 = str2double(extractBetween(str,'"pixel1":',','));
params.pixel2 = str2double(extractBetween(str,'"pixel2":',','));

end

%% detector rotations
function obj = applyRotations(obj,params)
vecs = [obj.detector.location; ... % obj.crystal.location is 0,0,0
    obj.detector.planePoints(1,:); ...
    obj.detector.planePoints(2,:)];
angs = [-params.Rot1, -params.Rot2, params.Rot3];
rotVecs = [0 0 1; 1 0 0; 0 1 0];
for ii = 1:numel(angs)
    for jj = 1:size(vecs,1)
        vecs(jj,:) = rotFun(vecs(jj,:),angs(ii),rotVecs(ii,:));
    end
end
obj.detector.location = vecs(1,:);
obj.detector.planePoints = vecs(2:3,:);
obj.detector.orientation = [0 0 0];
obj.detector.locationReference = [0 0 0];
obj.detector.orientationReference = [0 0 0];
end

function vec = rotFun(vec, ang, rotVec)
vec = vec*cos(ang) + cross(rotVec,vec,2)*sin(ang) + ...
    rotVec.*dot(rotVec,vec,2)*(1-cos(ang));
end

%% consistency checking
function problems = checkConsistencies(obj,params,conv,thresh)

problems = {};

d = abs(1e10*params.Wavelength-obj.source.lambda)/obj.source.lambda;
if d > thresh
    str = sprintf('X-ray wavelength mismatch of %g%%',100*d);
    problems = [problems, {str}];
    warning(str);
end

pixelVert = conv*obj.detector.size(1)/numel(obj.detector.image.Grid2);
pixelHorz = conv*obj.detector.size(2)/numel(obj.detector.image.Grid1);
d = abs([params.pixel1, params.pixel2] - [pixelVert, pixelHorz]) ./ ...
    [pixelVert, pixelHorz];
if any(d > thresh)
    str = sprintf('Pixel size mismatch of up to %g%%',max(100*d));
    problems = [problems,{str}];
    warning(str);
end

end
